<?php declare(strict_types=1);?><div class="page-header"><div><h1>Trip Plans</h1><p>Visitor itineraries will be created from the Member PWA using these Tourism trip-plan tables.</p></div></div><div class="card table-responsive"><table class="table"><thead><tr><th>Trip</th><th>Visitor</th><th>Dates</th><th>Items</th><th>Status</th></tr></thead><tbody><?php foreach($trips as $t):?><tr><td><strong><?=htmlspecialchars($t['title'])?></strong></td><td><?=htmlspecialchars((string)($t['user_name']??'—'))?></td><td><?=htmlspecialchars((string)($t['start_date']??'—').' → '.(string)($t['end_date']??'—'))?></td><td><?= (int)$t['item_count']?></td><td><?=htmlspecialchars($t['status'])?></td></tr><?php endforeach;if(!$trips):?><tr><td colspan="5">No visitor trip plans yet.</td></tr><?php endif;?></tbody></table></div>
